    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 7-year-old child refuses to bear weight on the right leg. The hip is held in flexion, abduction, and external rotation. Temperature is 39.0°C. Laboratory evaluation shows a WBC count of 15,000/mm³ and an ESR of 50 mm/hr. According to the Kocher criteria, what is the probability that this child has septic arthritis rather than transient synovitis?', '["> 90% (Very high probability)", "< 10% (Very low probability)", "Exactly 0%", "About 25%", "About 50%"]'::jsonb, 0, 'The Kocher criteria differentiate septic arthritis from transient synovitis. The 4 criteria are: non-weight-bearing, fever > 38.5°C, ESR > 40 mm/hr, and WBC > 12,000/mm³. Having all 4 predictors yields a 99% probability of septic arthritis; 3 predictors yield a 93% probability. This child has 4 predictors.'),
    (v_topic_id, 'Patient #71200: A 8-month-old infant is referred to orthopedics for asymmetric gluteal folds and a leg length discrepancy. Which imaging modality is considered the gold standard to evaluate for Developmental Dysplasia of the Hip (DDH) at this specific age?', '["AP radiograph of the pelvis", "MRI of the pelvis", "CT scan", "Ultrasound of the hips", "Bone scan"]'::jsonb, 0, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 6-year-old falls from a trampoline and sustains a significantly displaced extension-type supracondylar humerus fracture. Upon examination, the child is unable to make an ''OK'' sign (unable to flex the IP joint of the thumb and DIP joint of the index finger). Which nerve is most likely injured?', '["Anterior interosseous nerve (AIN)", "Axillary nerve", "Ulnar nerve", "Musculocutaneous nerve", "Radial nerve"]'::jsonb, 0, 'The anterior interosseous nerve (AIN), a branch of the median nerve, is the most commonly injured nerve in extension-type supracondylar humerus fractures. Injury manifests as an inability to flex the IP joint of the thumb (flexor pollicis longus) and the DIP of the index finger (flexor digitorum profundus), resulting in an inability to make the ''''A-OK'''' sign.'),
    (v_topic_id, 'A 8-week-old infant, born breech, presents for a routine well-child check. Examination reveals asymmetric thigh skin folds and a positive Ortolani maneuver on the bilateral. What is the most appropriate initial imaging modality to confirm the diagnosis?', '["Ultrasound of the hips", "Bone scan", "AP radiograph of the pelvis", "CT scan of the pelvis", "MRI of the hips"]'::jsonb, 0, 'Developmental Dysplasia of the Hip (DDH) is most accurately assessed with ultrasound in infants under 4-6 months of age because the femoral head and acetabulum are predominantly cartilaginous and not fully visible on radiographs. A positive Ortolani test (reduction of a dislocated hip) strongly suggests DDH.'),
    (v_topic_id, 'A 15-year-old female diver complains of insidious onset, mechanical low back pain that is exacerbated by extension activities (e.g., back walkovers). Neurologic exam is normal. Oblique radiographs of the lumbar spine demonstrate a ''collar'' on the ''Scotty dog''. What is the specific anatomic defect in this condition?', '["Defect in the pars interarticularis", "Defect in the vertebral body endplate (Schmorl node)", "Congenital failure of segmentation of the lumbar vertebrae", "Fracture of the transverse process", "Herniation of the nucleus pulposus"]'::jsonb, 0, 'Spondylolysis is a stress fracture or defect of the pars interarticularis. It is highly prevalent in adolescent athletes participating in sports involving repetitive lumbar hyperextension. On oblique radiographs, a radiolucent gap in the pars resembles a collar on the neck of the ''''Scotty dog''''.'),
    (v_topic_id, 'A 13-year-old track player complains of anterior knee pain that is worse after practice and jumping. Examination reveals point tenderness and a bony prominence over the tibial tubercle. Radiographs show fragmentation of the tibial tubercle apophysis. What is the most appropriate management?', '["Intra-articular corticosteroid injection", "Activity modification, ice, NSAIDs, and reassurance", "Strict non-weight bearing with crutches", "Immobilization in a long leg cast for 6 weeks", "Surgical excision of the ossicle"]'::jsonb, 1, 'Osgood-Schlatter disease is a traction apophysitis of the tibial tubercle, common in active adolescents experiencing rapid growth. It is a self-limiting condition. Treatment is symptomatic with rest, ice, NSAIDs, and physical therapy (quadriceps/hamstring stretching).'),
    (v_topic_id, 'A 5-month-old female infant is diagnosed with Developmental Dysplasia of the Hip (DDH) via ultrasound. The hip is reducible. What is the standard first-line treatment for this patient?', '["Open reduction and pelvic osteotomy", "Observation only", "Pavlik harness", "Triple diapering", "Closed reduction and spica casting"]'::jsonb, 2, 'For infants < 6 months of age with a reducible dysplastic or dislocated hip, the Pavlik harness is the gold standard treatment. It maintains the hip in flexion and abduction, promoting concentric reduction and acetabular remodeling. Closed reduction is typically reserved for failures or children 6-18 months.'),
    (v_topic_id, 'A 12-year-old heavy-set male presents with left groin and knee pain. He walks with a limp. On examination, when his left hip is passively flexed, it obligatorily goes into external rotation. Radiographs show a posterior and inferior displacement of the proximal femoral epiphysis. What is the most appropriate management?', '["Closed reduction and spica casting", "Physical therapy and weight loss", "Pavlik harness", "Open reduction and internal fixation", "Immediate non-weight bearing and in situ percutaneous pinning"]'::jsonb, 4, 'Slipped Capital Femoral Epiphysis (SCFE) occurs typically in overweight adolescents. The hallmark physical exam finding is obligatory external rotation with hip flexion. Treatment is strictly in situ pinning (without attempts at forceful closed reduction, which increases the risk of avascular necrosis) to stabilize the physis.'),
    (v_topic_id, 'A 5-week-old infant, born breech, presents for a routine well-child check. Examination reveals asymmetric thigh skin folds and a positive Ortolani maneuver on the right. What is the most appropriate initial imaging modality to confirm the diagnosis?', '["MRI of the hips", "Bone scan", "AP radiograph of the pelvis", "Ultrasound of the hips", "CT scan of the pelvis"]'::jsonb, 3, 'Developmental Dysplasia of the Hip (DDH) is most accurately assessed with ultrasound in infants under 4-6 months of age because the femoral head and acetabulum are predominantly cartilaginous and not fully visible on radiographs. A positive Ortolani test (reduction of a dislocated hip) strongly suggests DDH.'),
    (v_topic_id, 'Patient #6338: A 4-year-old child, who is at the 95th percentile for weight, presents with progressively worsening bowing of the left leg (genu varum). Radiographs show a prominent ''beak'' at the medial metaphysis of the proximal tibia. What is the diagnosis?', '["Physiologic genu varum", "Infantile Blount disease", "Achondroplasia", "Osgood-Schlatter disease", "Rickets"]'::jsonb, 1, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 13-year-old obese male presents with left groin and knee pain. He walks with a limp. On examination, when his left hip is passively flexed, it obligatorily goes into external rotation. Radiographs show a posterior and inferior displacement of the proximal femoral epiphysis. What is the most appropriate management?', '["Physical therapy and weight loss", "Open reduction and internal fixation", "Closed reduction and spica casting", "Immediate non-weight bearing and in situ percutaneous pinning", "Pavlik harness"]'::jsonb, 3, 'Slipped Capital Femoral Epiphysis (SCFE) occurs typically in overweight adolescents. The hallmark physical exam finding is obligatory external rotation with hip flexion. Treatment is strictly in situ pinning (without attempts at forceful closed reduction, which increases the risk of avascular necrosis) to stabilize the physis.'),
    (v_topic_id, 'A 9-day-old infant is brought to the clinic for unilateral right clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Cavus", "Equinus", "Varus", "Adductus", "Supination"]'::jsonb, 1, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'A 23-day-old infant is brought to the clinic for unilateral right clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Supination", "Cavus", "Varus", "Equinus", "Adductus"]'::jsonb, 3, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'A 14-year-old female gymnast complains of insidious onset, mechanical low back pain that is exacerbated by extension activities (e.g., back walkovers). Neurologic exam is normal. Oblique radiographs of the lumbar spine demonstrate a ''collar'' on the ''Scotty dog''. What is the specific anatomic defect in this condition?', '["Fracture of the transverse process", "Herniation of the nucleus pulposus", "Defect in the vertebral body endplate (Schmorl node)", "Defect in the pars interarticularis", "Congenital failure of segmentation of the lumbar vertebrae"]'::jsonb, 3, 'Spondylolysis is a stress fracture or defect of the pars interarticularis. It is highly prevalent in adolescent athletes participating in sports involving repetitive lumbar hyperextension. On oblique radiographs, a radiolucent gap in the pars resembles a collar on the neck of the ''''Scotty dog''''.'),
    (v_topic_id, 'A 26-day-old infant is brought to the clinic for unilateral left clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Cavus", "Varus", "Adductus", "Supination", "Equinus"]'::jsonb, 4, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'Patient #97686: A 3-year-old child presents to the ED refusing to bear weight on the leg after twisting it while running. Radiographs reveal a subtle, undisplaced spiral fracture of the distal tibial shaft. What is the diagnosis?', '["Salter-Harris I fracture", "Osteosarcoma", "Toddler''s fracture", "Osgood-Schlatter disease", "Non-accidental trauma (child abuse)"]'::jsonb, 2, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'Patient #28902: An 14-year-old overweight adolescent undergoes in situ pinning for a stable Slipped Capital Femoral Epiphysis (SCFE). At follow-up, the patient complains of severe stiffness and loss of joint space is noted on X-ray. What is this devastating complication?', '["Nonunion", "Avascular necrosis of the femoral head", "Infection", "Heterotopic ossification", "Chondrolysis"]'::jsonb, 4, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 10-year-old soccer player complains of anterior knee pain that is worse after practice and jumping. Examination reveals point tenderness and a bony prominence over the tibial tubercle. Radiographs show fragmentation of the tibial tubercle apophysis. What is the most appropriate management?', '["Strict non-weight bearing with crutches", "Intra-articular corticosteroid injection", "Activity modification, ice, NSAIDs, and reassurance", "Immobilization in a long leg cast for 6 weeks", "Surgical excision of the ossicle"]'::jsonb, 2, 'Osgood-Schlatter disease is a traction apophysitis of the tibial tubercle, common in active adolescents experiencing rapid growth. It is a self-limiting condition. Treatment is symptomatic with rest, ice, NSAIDs, and physical therapy (quadriceps/hamstring stretching).'),
    (v_topic_id, 'A 12-year-old basketball player presents with posterior heel pain. The pain worsens after running and improves with rest. Examination reveals tenderness upon medial-lateral compression of the calcaneal tuberosity (positive ''squeeze test''). There is tightness of the Achilles tendon. What is the most likely diagnosis?', '["Calcaneal stress fracture", "Calcaneal apophysitis (Sever disease)", "Achilles tendon rupture", "Tarsal coalition", "Plantar fasciitis"]'::jsonb, 1, 'Sever disease is a traction apophysitis of the calcaneus where the Achilles tendon inserts. It is a common cause of heel pain in athletic children aged 8-12. The classic exam finding is pain with medial/lateral compression of the heel. Treatment includes heel cups, calf stretching, and NSAIDs.'),
    (v_topic_id, 'Patient #60023: A 2-year-old child, who is at the 95th percentile for weight, presents with progressively worsening bowing of the left leg (genu varum). Radiographs show a prominent ''beak'' at the medial metaphysis of the proximal tibia. What is the diagnosis?', '["Achondroplasia", "Physiologic genu varum", "Osgood-Schlatter disease", "Rickets", "Infantile Blount disease"]'::jsonb, 4, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 9-day-old infant is brought to the clinic for unilateral left clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Equinus", "Cavus", "Varus", "Adductus", "Supination"]'::jsonb, 0, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'A 25-day-old infant is brought to the clinic for unilateral left clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Equinus", "Supination", "Cavus", "Adductus", "Varus"]'::jsonb, 0, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'Patient #30784: A 15-year-old boy presents with frequent ankle sprains and a painful, rigid flatfoot. Examination reveals severe restriction of subtalar motion and spasm of the peroneal muscles. Radiographs show a ''C-sign'' on the lateral view. What is the most likely diagnosis?', '["Flexible pes planus", "Calcaneonavicular coalition", "Posterior tibial tendon insufficiency", "Sever disease", "Talocalcaneal coalition"]'::jsonb, 4, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
